<?php require 'layout.php';require_login();if(!in_array(user()['role'],['admin','instructor'])){http_response_code(403);exit('Admins only.');}
if($_SERVER['REQUEST_METHOD']=='POST'){check_csrf();
 if(isset($_POST['invite'])&&user()['role']=='admin'){$em=strtolower(trim($_POST['invite']));if(filter_var($em,FILTER_VALIDATE_EMAIL))db()->prepare('INSERT INTO invites(email,token) VALUES(?,?)')->execute([$em,bin2hex(random_bytes(16))]);}
 elseif(isset($_POST['del']))db()->prepare('DELETE FROM items WHERE id=?')->execute([(int)$_POST['del']]);
 else{db()->prepare('INSERT INTO items(type,title,excerpt,body,category_id,author,minutes,image,url,featured) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$_POST['type'],trim($_POST['title']),trim($_POST['excerpt']),trim($_POST['body']),(int)$_POST['cat']?:null,trim($_POST['author'])?:'L2R Admin',max(1,(int)$_POST['minutes']),save_upload('cover',['jpg','jpeg','png','webp','gif'])?:(trim($_POST['image'])?:null),save_upload('media',['mp3','m4a','wav','ogg','mp4','webm','pdf','zip','html','png','jpg'])?:(trim($_POST['url'])?:null),isset($_POST['featured'])?1:0]);}
 go('admin.php');}
$cats=db()->query('SELECT * FROM categories')->fetchAll();hub_start('Manage content','dash');?>
<h1 class="h">Manage content</h1><p class="sub">Add resources to the Growth Hub.</p>
<form method="post" enctype="multipart/form-data" class="obcard" style="max-width:none"><?=csrf()?><div class="two"><label>Type<select name="type"><option value="article">Article</option><option value="podcast">Podcast</option><option value="video">Video</option><option value="download">Download</option></select></label><label>Category<select name="cat"><option value="0">None</option><?php foreach($cats as $c)echo '<option value="'.$c['id'].'">'.e($c['name']).'</option>';?></select></label></div>
<label>Title <span class="req">*</span><input name="title" required></label><label>Short summary<input name="excerpt" maxlength="400"></label><label>Body<textarea name="body" rows="6"></textarea></label>
<div class="two"><label>Author<input name="author" placeholder="L2R Admin"></label><label>Minutes<input type="number" name="minutes" value="5" min="1"></label></div>
<label>Cover image URL<input name="image" placeholder="https://..."></label><label>Media or file URL (YouTube link, audio, or download link)<input name="url"></label><label>Or upload a file (mp3, wav, mp4, pdf, zip, html)<input type="file" name="media"></label><label>Or upload a cover image<input type="file" name="cover" accept="image/*"></label>
