<table class="tbl"><?php foreach(db()->query('SELECT * FROM invites ORDER BY id DESC LIMIT 20') as $v):?><tr><td><?=e($v['email'])?></td><td><?=$v['used']?'Accepted':'<input readonly style="width:100%;height:30px;font-size:12px" onclick="this.select()" value="'.e((isset($_SERVER['HTTPS'])?'https':'http').'://'.$_SERVER['HTTP_HOST'].rtrim(dirname($_SERVER['SCRIPT_NAME']),'/').'/invite.php?token='.$v['token']).'">'?></td></tr><?php endforeach;?></table><?php endif;?>
<h2 class="h2">All resources</h2><table class="tbl"><?php foreach(items('1',[],200) as $it):?><tr><td><a href="item.php?id=<?=$it['id']?>"><?=e($it['title'])?></a></td><td><?=$it['type']?></td><td><form method="post" onsubmit="return confirm('Delete this resource?')"><?=csrf()?><button class="lnk" name="del" value="<?=$it['id']?>">Delete</button></form></td></tr><?php endforeach;?></table>
